package pe.edu.upeu.pago.client; import lombok.RequiredArgsConstructor; import org.springframework.beans.factory.annotation.Value; import org.springframework.stereotype.Component; import org.springframework.web.client.RestClient; import pe.edu.upeu.pago.dto.*; import pe.edu.upeu.pago.entity.OrdenCompra; import java.util.*; @Component @RequiredArgsConstructor public class MercadoPagoClient { private final RestClient mercadoPagoRestClient; @Value("${kido.mercadopago.access-token:}") private String token; @Value("${kido.mercadopago.notification-url:}") private String notificationUrl; public PreferenciaResponse crearPreferencia(OrdenCompra o){requireToken(); Map<String,Object> req=new LinkedHashMap<>(); req.put("items",List.of(Map.of("title",o.getCursoTitulo(),"quantity",1,"currency_id","PEN","unit_price",o.getMontoTotal()))); req.put("external_reference",String.valueOf(o.getId())); if(!notificationUrl.isBlank())req.put("notification_url",notificationUrl); @SuppressWarnings("unchecked") Map<String,Object> res=mercadoPagoRestClient.post().uri("/checkout/preferences").header("Authorization","Bearer "+token).body(req).retrieve().body(Map.class); return new PreferenciaResponse(str(res,"id"),str(res,"init_point"),str(res,"sandbox_init_point")); } public PagoExterno obtenerPago(String paymentId){requireToken(); @SuppressWarnings("unchecked") Map<String,Object> res=mercadoPagoRestClient.get().uri("/v1/payments/{id}",paymentId).header("Authorization","Bearer "+token).retrieve().body(Map.class); return new PagoExterno(str(res,"id"),str(res,"status"),str(res,"external_reference"),res==null?null:String.valueOf(res.get("transaction_amount"))); } public void reembolsar(String paymentId, java.math.BigDecimal amount, String idempotencyKey){requireToken(); mercadoPagoRestClient.post().uri("/v1/payments/{id}/refunds",paymentId).header("Authorization","Bearer "+token).header("X-Idempotency-Key",idempotencyKey).body(Map.of("amount",amount)).retrieve().toBodilessEntity(); } private void requireToken(){if(token==null||token.isBlank())throw new IllegalStateException("Configura MERCADO_PAGO_ACCESS_TOKEN con un token TEST de Mercado Pago sandbox");} private String str(Map<String,Object> m,String k){return m==null||m.get(k)==null?null:String.valueOf(m.get(k));} public record PagoExterno(String id,String status,String externalReference,String amount){} }